/**
 * OPD visits and billing: limits and defaults in one place (no magic numbers in the service).
 * Money is always integer paise.
 */
export const OPD_VISITS_CONFIG = {
  /** Payment mode used when the request names none (the master row is looked up by this code). */
  defaultPaymentModeCode: 'CASH',
  /** Idempotency key: one key per "Take payment" click, generated by the caller. */
  idempotencyKeyMinLength: 8,
  idempotencyKeyMaxLength: 64,
  /** Characters allowed in an idempotency key (no spaces, no personal data). */
  idempotencyKeyPattern: /^[A-Za-z0-9._:-]+$/,
  paymentModeCodeMaxLength: 32,
  /** Most payment lines (modes) one receipt can carry: UPI + cash + card + ... */
  maxPaymentLines: 4,
  referenceMaxLength: 64,
  idMaxLength: 64,
  listDefaultPageSize: 20,
  listMaxPageSize: 100,
  /** One retry when another request charged the same patient's registration fee at the same moment. */
  createMaxAttempts: 2,
  msPerDay: 24 * 60 * 60 * 1000,
  msPerHour: 60 * 60 * 1000,
  /** Largest amount (paise) the database stores (INTEGER). */
  maxAmountPaise: 2_147_483_647,
} as const;

/** Audit action names. */
export const OPD_AUDIT = {
  visitCreated: 'OPD_VISIT_CREATE',
  paymentReceived: 'OPD_PAYMENT_RECEIVE',
} as const;
